function pick(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
}

function normalizePhone(value) {
  const digits = String(value || '').replace(/\D/g, '');
  if (!digits) return '';
  if (digits.startsWith('55')) return digits;
  if (digits.length >= 10 && digits.length <= 11) return '55' + digits;
  return digits;
}

function normalizeText(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractTaskId(text) {
  const explicit = String(text || '').match(/(?:taskId|tarefaId|tarefa|id da tarefa|#tarefa)\s*[:#=-]?\s*([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})/i);
  if (explicit && explicit[1]) return explicit[1];
  const generic = String(text || '').match(/\b([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\b/i);
  return generic && generic[1] ? generic[1] : '';
}

function extractQuantity(text, fallback) {
  const direct = Number(fallback);
  if (Number.isFinite(direct) && direct > 0) return Math.trunc(direct);
  const matched = String(text || '').match(/(?:qtd|quantidade|realizei|realizado|realizada|convidei|convide|convidados|contatei|contatos|cadastrei|inseri|visitei|visitas|panfletei|panfletos|moradores|pessoas|eleitores|numeros|numeros)\D{0,30}(\d{1,5})/i);
  if (matched && matched[1]) return Math.max(1, Math.trunc(Number(matched[1])));
  return 1;
}

function inferActionType(text) {
  const normalized = normalizeText(text);
  const rules = [
    ['inserir_contatos', /\b(contatei|contato|contatos|numero|numeros|telefone|telefones|cadastrei|cadastro|inseri|inclui)\b/i],
    ['convidar_eventos', /\b(convidei|convidado|convidados|convite|convidar|evento|reuniao|reunioes|encontro)\b/i],
    ['captar_eleitores', /\b(captei|captacao|eleitor|eleitores|apoio|apoiador|voto|votos|adesao)\b/i],
    ['visitar_locais', /\b(visitei|visita|visitas|local|locais|comercio|lideranca|liderancas)\b/i],
    ['participar_reunioes', /\b(participei|participacao|reuniao|reunioes|encontro|agenda)\b/i],
    ['panfletar', /\b(panfletei|panfleto|panfletos|panfletagem|material|materiais)\b/i],
    ['divulgar_localidade', /\b(divulguei|divulgacao|divulgar|compartilhei|postei|publiquei)\b/i]
  ];
  return rules.find(([, pattern]) => pattern.test(normalized))?.[0] || '';
}

function looksLikeExecutionEvidence(text) {
  const normalized = normalizeText(text);
  if (!normalized) return false;
  const hasExecutionVerb = /\b(contatei|cadastrei|inseri|inclui|convidei|visitei|participei|panfletei|divulguei|compartilhei|postei|publiquei|captei|realizei|fiz|entreguei)\b/i.test(normalized);
  const hasQuantity = /\b\d{1,5}\b/.test(normalized);
  const hasActionObject = /\b(contato|contatos|numero|numeros|telefone|telefones|morador|moradores|pessoa|pessoas|eleitor|eleitores|convite|convites|reuniao|reunioes|visita|visitas|panfleto|panfletos|material|materiais)\b/i.test(normalized);
  return hasExecutionVerb && (hasQuantity || hasActionObject);
}

return items.map((item) => {
  const body = item.json.body || item.json.raw || item.json.metadata || {};
  const idCandidato = '1313';
  const mensagem = pick(item.json.mensagem_eleitor, item.json.chatInput, item.json.mensagem, item.json.message, item.json.text, body.chatInput, body.mensagem, body.message, body.text);
  const explicitTaskId = pick(item.json.taskId, item.json.tarefaId, body.taskId, body.tarefaId, body.tarefa_id);
  const taskId = explicitTaskId || extractTaskId(mensagem);
  const telefone = normalizePhone(pick(item.json.telefone, item.json.phone, item.json.memberPhone, item.json.whatsapp, body.telefone, body.phone, body.memberPhone, body.whatsapp, body.from));
  const quantidadeValidada = extractQuantity(mensagem, pick(item.json.quantidadeValidada, item.json.quantidade, body.quantidadeValidada, body.quantidade));
  const tipoAcao = inferActionType(mensagem);
  const naturalEvidence = looksLikeExecutionEvidence(mensagem);
  const n8nBase = pick($env.N8N_WEBHOOK_BASE_URL, $env.N8N_BASE_URL, $env.WEBHOOK_BASE_URL).replace(/\/$/, '');
  const defaultWebhookBase = 'https://n8n-n8n-start.kb0fgy.easypanel.host/webhook';
  const webhookBase = n8nBase ? (n8nBase.endsWith('/webhook') ? n8nBase : n8nBase + '/webhook') : defaultWebhookBase;
  const shouldDispatch = Boolean((taskId || naturalEvidence) && telefone && webhookBase);
  const errors = [];

  if ((taskId || naturalEvidence) && !telefone) errors.push('telefone do membro ausente para registrar evidencia de divulgacao.');

  return {
    json: {
      ...item.json,
      evidencia_divulgacao_detectada: Boolean(taskId || naturalEvidence),
      evidencia_divulgacao_valida: shouldDispatch,
      evidencia_divulgacao_erros: errors,
      evidencia_divulgacao_payload: {
        idCandidato,
        taskId,
        telefone,
        mensagem,
        quantidade: quantidadeValidada,
        tipoAcao,
        canal: 'whatsapp',
        origem: taskId ? '02b-funil-whatsapp-task-id' : '02b-funil-whatsapp-natural'
      },
      evidencia_divulgacao_webhook_url: shouldDispatch ? webhookBase + '/agente-politico/' + encodeURIComponent(idCandidato) + '/divulgacao/evidencias' : ''
    }
  };
});
